import math

@test("Shape can't be instantiated")
def _():
    raises(TypeError, Shape)

@test("a subclass missing a method can't be instantiated")
def _():
    class OnlyArea(Shape):
        def area(self):
            return 1
    raises(TypeError, OnlyArea)

@test("areas and perimeters")
def _():
    assert math.isclose(Circle(1).area(), math.pi)
    assert math.isclose(Circle(1).perimeter(), 2 * math.pi)
    assert Rectangle(2, 3).area() == 6 and Rectangle(2, 3).perimeter() == 10
    assert Square(4).area() == 16 and Square(4).perimeter() == 16

@test("non-positive dimensions raise ValueError")
def _():
    raises(ValueError, Circle, 0)
    raises(ValueError, Rectangle, 2, -1)
    raises(ValueError, Square, -3)

@test("shapes sort by area")
def _():
    shapes = [Square(3), Circle(1), Rectangle(1, 2)]
    names = [type(s).__name__ for s in sorted(shapes)]
    assert names == ["Rectangle", "Circle", "Square"], f"sorted order: {names}"

@test("describe() is defined once, on Shape")
def _():
    assert Circle(1).describe() == "Circle with area 3.14", f"got {Circle(1).describe()!r}"
    assert Square(2).describe() == "Square with area 4.00"
    for cls in (Circle, Rectangle, Square):
        assert "describe" not in vars(cls), f"{cls.__name__} overrides describe()"

@test("total_area sums the areas")
def _():
    assert math.isclose(total_area([Square(2), Rectangle(1, 3)]), 7)
    assert total_area([]) == 0

